import { Array, Match as M, Schema as S } from "effect";
import type { Command as FoldkitCommand } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as Command from "../../ui/command";

// MODEL

export const Model = S.Struct({
  query: S.String,
});
export type Model = typeof Model.Type;

// MESSAGE

export const UpdatedCommandQuery = m("UpdatedCommandQuery", {
  value: S.String,
});

export const Message = S.Union([UpdatedCommandQuery]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly FoldkitCommand.Command<Message>[],
] => [{ query: "" }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly FoldkitCommand.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly FoldkitCommand.Command<Message>[]]>(),
    M.tagsExhaustive({
      UpdatedCommandQuery: ({ value }) => [
        evo(model, { query: () => value }),
        [],
      ],
    })
  );

// VIEW

const items: readonly Command.CommandItem[] = [
  { group: "Suggestions", label: "Calendar" },
  { group: "Suggestions", label: "Search Emoji" },
  { group: "Suggestions", label: "Calculator" },
  { group: "Settings", label: "Profile", shortcut: "⌘P" },
  { group: "Settings", label: "Billing", shortcut: "⌘B" },
  { group: "Settings", label: "Settings", shortcut: "⌘S" },
  { group: "Pages", label: "Dashboard" },
  { group: "Pages", label: "Projects" },
  { group: "Pages", label: "Tasks" },
  { group: "Pages", label: "Reporting" },
  { group: "Pages", label: "Notifications" },
  { group: "Pages", label: "Support" },
];

const groupedItems = (
  commandItems: readonly Command.CommandItem[]
): readonly [string, readonly Command.CommandItem[]][] =>
  Array.dedupe(commandItems.map((item) => item.group)).map((group) => [
    group,
    commandItems.filter((item) => item.group === group),
  ]);

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const filteredItems = Command.filterItems(items, model.query);

  return Command.rootView<Message>({
    className: "max-w-md",
    children: [
      Command.inputView<Message>({
        value: model.query,
        onInput: (value) => UpdatedCommandQuery({ value }),
      }),
      Command.listView<Message>({
        className: "max-h-48",
        children:
          filteredItems.length === 0
            ? [Command.emptyView<Message>({ children: ["No results found."] })]
            : groupedItems(filteredItems).flatMap(
                ([group, groupItems], index) => [
                  ...(index === 0 ? [] : [Command.separatorView<Message>()]),
                  Command.groupView<Message>({
                    heading: group,
                    children: groupItems.map((item) =>
                      Command.itemView<Message>({ item })
                    ),
                  }),
                ]
              ),
      }),
    ],
  });
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as Example from "./main";

describe("Command Scrollable example", () => {
  test("renders a longer scrollable command list", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.expect(Scene.text("Pages")).toExist(),
      Scene.expect(Scene.role("option", { name: "Dashboard" })).toExist(),
      Scene.expect(Scene.role("option", { name: "Support" })).toExist(),
      Scene.expect(Scene.role("option", { name: "Dashboard" })).not.toHaveHandler(
        "click"
      )
    );
  });

  test("filters scrollable command content", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.type(Scene.role("combobox", { name: "Command search" }), "report"),
      Scene.expect(Scene.role("option", { name: "Reporting" })).toExist(),
      Scene.expect(Scene.role("option", { name: "Dashboard" })).toBeAbsent()
    );
  });

  test("renders empty scrollable command results", () => {
    Scene.scene(
      { update: Example.update, view: Example.view },
      Scene.with(Example.init()[0]),
      Scene.type(Scene.role("combobox", { name: "Command search" }), "zzz"),
      Scene.expect(Scene.text("No results found.")).toExist()
    );
  });
});
